            </button>,
          )}
          <div
            aria-hidden
            className="my-2 h-px w-7 shrink-0 bg-fp-shell-guide"
          />
          {sections.map((sec, i) => (
            <React.Fragment key={sec.heading ?? `loose-${i}`}>
