        </Tooltip>
        <ul className="flex min-h-0 flex-1 flex-col gap-1 overflow-y-auto px-2.5 pt-7 pb-3">
          {/* THE OPEN MODULE GOES FIRST (Pavan, 2026-10-06); the rest follow
            in their usual order. */}
          {[
            ...modules.filter((m) => m.key === view.first),
            ...modules.filter((m) => m.key !== view.first),
