export function matchesAssetOrder(row: AssetOrder, q: string): boolean {
  return [
    row.orderNo,
    row.customer.title,
    row.customer.description,
    row.salesRep,
    row.date.title,
    row.status,
    row.assetType,
    row.serialNo,
    row.poNumber,
  ]
    .join(" ")
    .toLowerCase()
    .includes(q);
}

