const dayKey = (offset: number) => {
  const d = startOfDay(new Date());
  d.setDate(d.getDate() + offset);
  return dateKeyOf(d);
};
const isoAt = (offset: number, hour: number) => {
  const d = startOfDay(new Date());
  d.setDate(d.getDate() + offset);
  d.setHours(hour, 15);
  return d.toISOString();
};

