  unit: string;
  quantityPrecision: number;
  minimumQuantity: number | null;
  maximumQuantity: number | null;
  defaultQuantity: number | null;
  /**
   * TOP-OFF IS A PRODUCT CAPABILITY, not an order-time whim. An order line can
