  availableVendorIds: string[];
  defaultVendorIds: string[];
  geographyRestrictions: string[];

  /* ── safety ── */
  /** Hazard class as it appears on the BOL. */
  hazmat: string | null;
  hazardFlags: string[];
  sdsAttachments: Attachment[];

  /* ── record ── */
  tags: string[];
  notes: string | null;
  attachments: Attachment[];
  audit: AuditEvent[];
  displayOrder: number;
  createdAt: string;
  updatedAt: string;
}

