import * as React from "react";
import { Check, CircleCheck } from "lucide-react";
import { MODULES, type Module } from "./data";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from "@/components/ui/dropdown-menu";

/** Completion celebration — a white check-circle that pops in. Linear/clean per the DS. */
function CompletionBurst() {
  return (
    <CircleCheck
      className="module-check-pop size-5 shrink-0 text-brand-foreground"
      strokeWidth={2.25}
    />
  );
}

export interface ModuleSwitcherProps {
  /** Pins the rail open while the menu is up. */
  onOpenChange?: (open: boolean) => void;
  /**
   * CONTROLLED mode — the active module key. Omit for the uncontrolled
   * behaviour (the switcher remembers its own selection, which is all the DS
   * gallery needs).
   */
  activeModule?: string;
  /**
   * Fires once the switch actually commits — i.e. AFTER the progress bar, at the
   * same moment the tick appears, not on click. An app that swaps its whole
   * navigation on this must not do it under the user's cursor mid-animation.
   */
  onModuleChange?: (key: string) => void;
  /**
   * The modules to offer. Defaults to the DS's own sample list, which is all
   * the gallery needs; an application passes its real one rather than editing
   * the DS's data file to add a module only that application has.
   */
  modules?: Module[];
}

/**
 * Tier-1 rail module switcher (top of the rail). Shows the active module —
 * icon-only when the rail is collapsed, icon + name when expanded. Opening it
 * pins the rail open (via `onOpenChange`) and drops a menu below the trigger, so
 * the switch happens inside the open rail.
 *
 * Controlled or uncontrolled. Pass `activeModule` + `onModuleChange` when the
 * module drives real routing (the Unified View prototype does); pass neither and
 * it keeps its own state, which is the gallery's case. The switch animation is
 * identical either way — only where the resulting selection is stored moves.
 */
export function ModuleSwitcher({
  onOpenChange,
  activeModule,
  onModuleChange,
  modules = MODULES,
}: ModuleSwitcherProps) {
  const [open, setOpen] = React.useState(false);
  const [ownKey, setOwnKey] = React.useState("sales");
  const [switchingKey, setSwitchingKey] = React.useState<string | null>(null);
  const [completedKey, setCompletedKey] = React.useState<string | null>(null);
  // Controlled when `activeModule` is supplied; otherwise the local key wins.
  const activeKey = activeModule ?? ownKey;
  const active = modules.find((m) => m.key === activeKey) ?? modules[0];

  const setMenuOpen = (o: boolean) => {
    setOpen(o);
    onOpenChange?.(o);
  };

  // On select: keep the menu open, run a quick left→right progress bar, then a
  // completion burst (circle + tick + slight confetti), then close the popup.
  const selectModule = (key: string) => (e: Event) => {
    e.preventDefault();
    if (switchingKey || completedKey) return;
    setSwitchingKey(key);
    window.setTimeout(() => {
      setOwnKey(key);
      onModuleChange?.(key);
      setSwitchingKey(null);
      setCompletedKey(key);
      window.setTimeout(() => {
        setCompletedKey(null);
        setMenuOpen(false);
      }, 750);
    }, 600);
  };

  return (
    <DropdownMenu open={open} onOpenChange={setMenuOpen}>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          aria-label={`Module: ${active.name}. Click to switch module`}
          className="flex shrink-0 items-center gap-2 rounded-md px-2.5 py-1 text-left outline-none transition-colors hover:bg-sidebar-accent-hover focus-visible:ring-2 focus-visible:ring-ring/50 data-[state=open]:bg-sidebar-accent/60"
        >
          <span className="flex size-8 shrink-0 items-center justify-center rounded-md bg-sidebar-accent text-sidebar-foreground [&_svg]:size-5">
            {active.icon}
          </span>
          <span className="min-w-0 flex-1 truncate text-sm font-semibold text-sidebar-foreground opacity-0 transition-opacity duration-150 group-hover:opacity-100 group-data-[expanded=true]:opacity-100">
            {active.name}
          </span>
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        side="bottom"
        align="start"
        sideOffset={6}
        className="w-[var(--radix-dropdown-menu-trigger-width)]"
      >
        {modules.map((m) => {
          const isSwitching = switchingKey === m.key;
          const isCompleting = completedKey === m.key;
          return (
            <DropdownMenuItem
              key={m.key}
              onSelect={selectModule(m.key)}
              className="relative gap-2"
            >
              <span className="flex size-6 shrink-0 items-center justify-center rounded bg-sidebar-accent text-sidebar-foreground [&_svg]:size-4">
                {m.icon}
              </span>
              <span className="flex-1 truncate">{m.name}</span>
              {isCompleting ? (
                <CompletionBurst />
              ) : m.key === activeKey && !isSwitching ? (
                <Check className="size-4 shrink-0 text-foreground duration-200 animate-in zoom-in-50 fade-in" />
              ) : null}
              {isSwitching && (
                <span
                  className="module-switch-progress pointer-events-none absolute inset-x-1 bottom-0.5 h-0.5 rounded-full bg-brand"
                  aria-hidden
                />
              )}
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import type { NavGroup } from "./types";
import { ModuleSwitcher } from "./ModuleSwitcher";
import type { Module } from "./data";

export interface NavRailProps {
  groups: NavGroup[];
  activeKey?: string;
  onNavigate?: (key: string) => void;
  /**
   * Active module, forwarded to the `ModuleSwitcher`. Supply this together with
   * `onModuleChange` when the module drives which `groups` the rail is given —
   * i.e. when switching module swaps the whole destination list rather than just
   * relabelling the tile.
   */
  activeModule?: string;
  onModuleChange?: (key: string) => void;
  /** Passed straight through to `ModuleSwitcher` — see its `modules` prop. */
  modules?: Module[];
}

/**
 * Tier-1 icon rail that expands to a 256px labeled drawer on hover —
 * Figma "Main Navigation Menu Interaction" (node 27634:21171).
 *
 * Collapsed 52px (`bg-rail` #080808). On hover — or while the module switcher is
 * open — it expands to 256px as an **overlay**; the 52px footprint stays reserved
 * so content never reflows; icons keep position and labels fade in. The surface
 * stays `bg-rail` in both states (the colour does not change on expand).
 */
export function NavRail({
  groups,
  activeKey,
  onNavigate,
  activeModule,
  onModuleChange,
  modules,
}: NavRailProps) {
  const [moduleOpen, setModuleOpen] = React.useState(false);
  /**
   * PICKING SOMETHING IS FINISHING WITH THE RAIL.
   *
   * Hover alone cannot say that. The pointer is still on the rail the instant
   * after the click, so the panel stays open over the very thing the click
   * asked to see — the reader has to move away to find out whether anything
   * happened. Sticking there is the rail answering a question nobody asked
   * twice, and it is the one moment in the interaction where the system's
   * state and the reader's intent are plainly different.
   *
   * So a click puts the rail back to 52px and keeps it there until the pointer
   * leaves — hovering again is a new question and gets the panel back.
   */
  const [dismissed, setDismissed] = React.useState(false);
  const box = React.useRef<HTMLDivElement>(null);
  React.useEffect(() => {
    if (!dismissed) return;
    /* POSITION, NOT `mouseleave`. The rail collapses out from under the
       cursor, and a browser owes no leave for an element that shrank away from
       a pointer that never moved. */
    const move = (e: PointerEvent) => {
      const t = e.target;
      if (!(t instanceof Node) || !box.current?.contains(t)) setDismissed(false);
    };
    document.addEventListener("pointermove", move, true);
    return () => document.removeEventListener("pointermove", move, true);
  }, [dismissed]);

  return (
    // reserves the 52px footprint; the panel below overlays on hover
    <div ref={box} className="relative h-full w-[52px] shrink-0">
      <nav
        aria-label="Primary"
        data-expanded={moduleOpen ? "true" : undefined}
        className={cn(
          "group absolute inset-y-0 left-0 z-30 flex w-[52px] flex-col overflow-hidden",
          "bg-rail py-3 shadow-none transition-[width,box-shadow] duration-200 ease-out",
          !dismissed && "hover:w-64 hover:shadow-xl",
          "data-[expanded=true]:w-64 data-[expanded=true]:shadow-xl"
        )}
      >
        {/* Module switcher — top: the selected module. Opening it pins the rail open. */}
        <ModuleSwitcher
          onOpenChange={setModuleOpen}
          activeModule={activeModule}
          onModuleChange={onModuleChange}
          modules={modules}
        />

        {/* Divider — clear separation between the module and its menus */}
        <div className="mx-2 my-3 h-px shrink-0 bg-sidebar-border" aria-hidden />

        {/* Nav groups — the menus for the selected module (nested children belong to tier-2) */}
        <div className="flex flex-1 flex-col gap-4">
          {groups.map((group, i) => (
            <ul key={group.label ?? i} className="flex flex-col gap-1">
              {group.items.map((item) => {
                const active = item.key === activeKey;
                return (
                  <li key={item.key}>
                    <button
                      type="button"
                      aria-label={item.label}
                      aria-current={active ? "page" : undefined}
                      onClick={() => {
                        onNavigate?.(item.key);
                        setDismissed(true);
                      }}
                      className={cn(
                        "relative flex h-9 w-full items-center gap-1 px-2 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50 [&_svg]:size-5",
                        active
                          ? "text-sidebar-foreground before:absolute before:left-0 before:h-7 before:w-0.5 before:bg-brand"
                          : "text-sidebar-foreground/70 hover:text-sidebar-foreground"
                      )}
                    >
                      {/* THE SELECTED AREA KEEPS A TILE (Pavan, 2026-10-05) —
                          the same fill drawer 2 gives its selected item, so
                          with the rail collapsed the reader can still see
                          where they went. 36px, centred in the 52px rail. */}
                      <span
                        className={cn(
                          "flex size-9 shrink-0 items-center justify-center rounded-md transition-colors",
                          active && "bg-sidebar-accent text-sidebar-accent-foreground"
                        )}
                      >
                        {item.icon}
                      </span>
                      <span
                        className={cn(
                          "truncate opacity-0 transition-opacity duration-150 group-data-[expanded=true]:opacity-100",
                          !dismissed && "group-hover:opacity-100"
                        )}
                      >
                        {item.label}
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          ))}
        </div>
      </nav>
    </div>
  );
}

import * as React from "react";
import { ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import type { NavGroup, NavItem, NavBrand } from "./types";

export interface NavigationDrawerProps {
  brand: NavBrand;
  groups: NavGroup[];
  /** key of the active item / sub-item */
  activeKey?: string;
  /** Collapsed = 52px icon rail; expanded = 256px labeled drawer. */
  collapsed?: boolean;
  onNavigate?: (key: string) => void;
  /** Override the surface/shape — e.g. tier-2 contextual sidebar adds shadow + radius. */
  className?: string;
}

/**
 * Figma "Navigation Drawer" (node 27634:24684) — supports the
 * Expanded (256px) and Default/collapsed (52px) states.
 */
export function NavigationDrawer({
  brand,
  groups,
  activeKey,
  collapsed = false,
  onNavigate,
  className,
}: NavigationDrawerProps) {
  return (
    <nav
      aria-label="Primary"
      className={cn(
        "flex h-full shrink-0 flex-col bg-sidebar text-sidebar-foreground",
        collapsed ? "w-[52px] items-center py-3" : "w-64 p-2",
        className
      )}
    >
      <BrandHeader brand={brand} collapsed={collapsed} />

      <div
        className={cn(
          "flex flex-1 flex-col",
          collapsed ? "mt-7 gap-3.5" : "mt-2 gap-4"
        )}
      >
        {groups.map((group, i) => (
          <Group
            key={group.label ?? i}
            group={group}
            collapsed={collapsed}
            activeKey={activeKey}
            onNavigate={onNavigate}
          />
        ))}
      </div>
    </nav>
  );
}

function BrandHeader({ brand, collapsed }: { brand: NavBrand; collapsed: boolean }) {
  const tile = (
    /* THE TILE IS THE TITLE'S OWN LINE BOX — 24px, the height of the 16px name
       beside it. At 36 it was half again as tall as the word it belongs to and
       read as a separate object sitting next to the heading rather than as its
       mark. */
    <span
      className={cn(
        "flex size-6 shrink-0 items-center justify-center rounded-md text-sidebar-primary-foreground [&_svg]:size-3.5",
        brand.iconClassName ?? "bg-sidebar-primary"
      )}
    >
      {brand.icon}
    </span>
  );
  if (collapsed) return tile;
  return (
    <div className="flex h-12 items-center gap-2 px-2">
      {tile}
      <span className="truncate text-base font-semibold text-sidebar-foreground">{brand.name}</span>
    </div>
  );
}

function Group({
  group,
  collapsed,
  activeKey,
  onNavigate,
}: {
  group: NavGroup;
  collapsed: boolean;
  activeKey?: string;
  onNavigate?: (key: string) => void;
}) {
  return (
    <div className="flex flex-col gap-1">
      {group.label && !collapsed && (
        <p className="px-2 py-1 text-xs font-medium text-foreground">{group.label}</p>
      )}
      <ul className={cn("flex flex-col", collapsed ? "items-center gap-3.5" : "gap-0.5")}>
        {group.items.map((item) => (
          <Item
            key={item.key}
            item={item}
            collapsed={collapsed}
            activeKey={activeKey}
            onNavigate={onNavigate}
          />
        ))}
      </ul>
    </div>
  );
}

function Item({
  item,
  collapsed,
  activeKey,
  onNavigate,
}: {
  item: NavItem;
  collapsed: boolean;
  activeKey?: string;
  onNavigate?: (key: string) => void;
}) {
  const hasChildren = !!item.children?.length;
  const childActive = item.children?.some((c) => c.key === activeKey);
  const [open, setOpen] = React.useState<boolean>(!!childActive);
  const active = item.key === activeKey;

  // Collapsed rail: icon-only button.
  if (collapsed) {
    return (
      <li>
        <button
          type="button"
          aria-label={item.label}
          aria-current={active ? "page" : undefined}
          onClick={() => onNavigate?.(item.key)}
          className={cn(
            "flex size-7 items-center justify-center rounded-md text-sidebar-foreground/70 outline-none transition-colors hover:text-sidebar-foreground focus-visible:ring-2 focus-visible:ring-ring/50 [&_svg]:size-5",
            active && "bg-sidebar-accent text-sidebar-accent-foreground"
          )}
        >
          {item.icon}
        </button>
      </li>
    );
  }

  return (
    <li>
      <button
        type="button"
        aria-current={active ? "page" : undefined}
        aria-expanded={hasChildren ? open : undefined}
        onClick={() => (hasChildren ? setOpen((v) => !v) : onNavigate?.(item.key))}
        className={cn(
          "flex w-full items-center gap-3 rounded-lg px-4 py-1 text-sm font-medium outline-none transition-colors hover:bg-sidebar-accent-hover focus-visible:ring-2 focus-visible:ring-ring/50 [&_svg]:size-5",
          active
            ? "bg-sidebar-accent text-sidebar-accent-foreground"
            : "text-muted-foreground hover:text-sidebar-foreground"
        )}
      >
        {item.icon}
        <span className="flex-1 truncate text-left">{item.label}</span>
        {hasChildren && (
          <ChevronRight
            className={cn("!size-4 transition-transform", open && "rotate-90")}
          />
        )}
      </button>

      {hasChildren && open && (
        <ul className="mt-0.5 flex flex-col gap-1 py-0.5 pl-6">
          {item.children!.map((sub) => {
            const subActive = sub.key === activeKey;
            return (
              <li key={sub.key}>
                <button
                  type="button"
                  aria-current={subActive ? "page" : undefined}
                  onClick={() => onNavigate?.(sub.key)}
                  className={cn(
                    "flex w-full items-center rounded-md px-2 py-1.5 text-sm outline-none transition-colors hover:bg-sidebar-accent-hover focus-visible:ring-2 focus-visible:ring-ring/50",
                    subActive
                      ? "bg-sidebar-accent text-sidebar-accent-foreground"
                      : "text-muted-foreground hover:text-sidebar-foreground"
                  )}
                >
                  {sub.label}
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </li>
  );
}

