/** Side-sheet variants a row action can open (typed inline to avoid a cycle). */
export type RowSheetVariant = "narrow" | "wide" | "dense";

export interface DataTableProps {
  rows: TableRowData[];
  selectedIds: Set<string>;
  onToggleRow: (id: string) => void;
  onToggleAll: (checked: boolean) => void;
  /** Select or clear a whole group at once. Required once `nodes` is passed. */
  onToggleGroup?: (ids: string[], checked: boolean) => void;
  /** Current sort (owned by the parent so it can sort the full dataset). */
  sort: SortState | null;
  /** Toggle sort for a column (parent cycles asc → desc → unsorted). */
  onSort: (key: ColumnKey) => void;
  /** Open a side sheet from a row action. Omit to hide those menu items. */
  onRowAction?: (variant: RowSheetVariant, row: TableRowData) => void;
  /** Hidden column keys (driven by the action bar's column-filters menu). */
  hidden?: Set<ColumnKey>;
  /** Optional control rendered in the header's rightmost cell, revealed on
   *  header hover (e.g. the column tools popover). */
  headerAction?: React.ReactNode;
  /* GROUPING. The table renders what the engine already computed and owns none
     of it — pass `nodes` and it draws headers between the rows, omit them and
     it is the flat table it has always been. A table that decided its own
     grouping would be a second implementation of `groupRows` to keep in step
     with the first. */
  nodes?: GroupNode<TableRowData>[];
  collapsedGroups?: ReadonlySet<string>;
  onToggleGroupCollapse?: (id: string) => void;
  /** Unit for the summed measure on each header, e.g. `gal`. */
  groupUnit?: string;
  /** What one record is called here — "order", "asset", "record". */
  groupNoun?: string;
}

export function DataTable({
  rows,
  selectedIds,
  onToggleRow,
  onToggleAll,
  onToggleGroup,
  sort,
  onSort,
  onRowAction,
  hidden,
  headerAction,
  nodes,
  collapsedGroups,
  onToggleGroupCollapse,
  groupUnit = "",
  groupNoun = "record",
}: DataTableProps) {
  // Cell edits live here (keyed by row id) rather than inside Row: rows unmount
  // when the page changes, and an edit must outlive that.
  const [edits, setEdits] = React.useState<Record<string, string>>({});
  const { editableIcons } = usePreferences();

  const allSelected = rows.length > 0 && rows.every((r) => selectedIds.has(r.id));
  const someSelected = rows.some((r) => selectedIds.has(r.id));
  const headerState = allSelected ? true : someSelected ? "indeterminate" : false;
  /* THE DEFAULT, NOT A FEATURE. Every table's columns move and resize; the DS
     header carries both, so this is the whole of the wiring — which of these
     columns are structure rather than content. */
  const cols = useTableColumns({
    keys: React.useMemo(() => COLUMNS.map((c) => c.key), []),
    fixed: FIXED_COLUMNS,
  });
  const visibleColumns = cols.arrange(COLUMNS.filter((c) => !hidden?.has(c.key)));

  // Measure the scroll viewport so an expanded row's detail can fill the VISIBLE
  // width (not the table's much wider scroll width) — its columns then sit
  // comfortably like the reference and stay pinned as the grid scrolls sideways.
  const scrollRef = React.useRef<HTMLDivElement>(null);
  const [viewportWidth, setViewportWidth] = React.useState<number>();
  React.useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const measure = () => setViewportWidth(el.clientWidth);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return (
    // Outer stroke around the whole table (Figma 28165:3758) — bound to the
    // `border` token (follows the FP variable; updated to FP/Outline 1), rounded.
    // This element owns BOTH scroll axes so the sticky header pins to its top; the
    // shadcn <Table> wraps the table in its own `overflow-x-auto` div — neutralize
    // it (`table-container` → overflow-visible) so THIS element is the sticky
    // header's scroll anchor, not that inner wrapper.
    <div
      ref={scrollRef}
      className="h-full overflow-auto rounded-md border border-border [&_[data-slot=table-container]]:overflow-visible"
    >
      <Table style={{ tableLayout: "fixed" }}>
        <colgroup>
          {visibleColumns.map((c) => (
            <col key={c.key} style={{ width: `${cols.widthOf(c)}px` }} />
          ))}
        </colgroup>
        <TableHeader className="sticky top-0 z-20">
          <TableRow className="group/hdr h-10">
            {visibleColumns.map((col) => {
              const active = sort?.key === col.key;
              const SortIcon = !active
                ? ChevronsUpDown
                : sort.dir === "asc"
                  ? ArrowUp
                  : ArrowDown;
              return (
                <TableColumnHeader
                  key={col.key}
                  cols={cols}
                  col={col}
                  aria-sort={
                    active ? (sort.dir === "asc" ? "ascending" : "descending") : undefined
                  }
                  className={cn(
                    // Solid fill (Surface 1a) + bottom hairline so body rows
                    // scroll UNDER the header, not through the titles. Stickiness
                    // is on the <thead> (th-level sticky is unreliable with
                    // collapsed table borders).
                    "border-b border-fp-outline-1 bg-fp-table-header px-3 text-xs font-medium text-muted-foreground",
                    col.align === "right" && "text-right"
                  )}
                >
                  {col.key === "select" ? (
                    <Checkbox
                      checked={headerState}
                      onCheckedChange={(c) => onToggleAll(c === true)}
                      aria-label="Select all rows"
                    />
                  ) : col.label && col.sortable ? (
                    <button
                      type="button"
                      onClick={() => onSort(col.key)}
                      aria-label={`Sort by ${col.label}`}
                      className={cn(
                        "inline-flex items-center gap-1 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50",
                        active && "text-foreground",
                        col.align === "right" && "flex-row-reverse"
                      )}
                    >
                      {col.label}
                      <SortIcon
                        className={cn("size-3.5", active ? "opacity-100" : "opacity-70")}
                      />
                    </button>
                  ) : col.label ? (
                    <span>{col.label}</span>
                  ) : col.key === "actions" ? (
                    <div className="flex justify-end">{headerAction}</div>
                  ) : null}
                </TableColumnHeader>
              );
            })}
          </TableRow>
        </TableHeader>
        <TableBody>
          {(
            nodes ??
            rows.map((row) => ({
              kind: "row" as const,
              id: row.id,
              depth: 0,
              row,
            }))
          ).map((node, idx) =>
            node.kind === "group" ? (
              <GroupHeaderRow
                key={node.id}
                /* +1 for the selection column, which is not in `COLUMNS`. */
                colSpan={visibleColumns.length + 1}
                depth={node.depth}
                label={node.label}
                dimLabel={node.dimLabel}
                count={node.count}
                measure={node.measure}
                unit={groupUnit}
                noun={groupNoun}
                collapsed={Boolean(collapsedGroups?.has(node.id))}
                onToggle={() => onToggleGroupCollapse?.(node.id)}
                /* Reads the group's WHOLE membership, so a collapsed group
                   still reports honestly rather than describing the rows that
                   happen to be drawn. */
                selection={{
                  state: groupSelectionState(node.rowIds, selectedIds),
                  onChange: (checked) => onToggleGroup?.(node.rowIds, checked),
                }}
              />
            ) : (
              <Row
                key={node.id}
                row={node.row}
                columns={visibleColumns}
                selected={selectedIds.has(node.row.id)}
                onToggle={() => onToggleRow(node.row.id)}
                onRowAction={onRowAction}
                // First row demonstrates an expandable nested sub-table.
                expandable={!nodes && idx === 0}
                detailWidth={viewportWidth}
                editableValue={edits[node.row.id] ?? node.row.editable}
                onEditableChange={(next) =>
                  setEdits((prev) => ({ ...prev, [node.row.id]: next }))
                }
                editableIcons={editableIcons}
              />
            )
          )}
        </TableBody>
      </Table>
    </div>
  );
}

function Row({
  row,
  columns,
  selected,
  onToggle,
  onRowAction,
  expandable = false,
  detailWidth,
  editableValue,
  onEditableChange,
  editableIcons,
}: {
  row: TableRowData;
  columns: ColumnDef[];
  selected: boolean;
  onToggle: () => void;
  editableValue: string;
  onEditableChange: (next: string) => void;
  editableIcons: Record<"leading" | "trailing", boolean>;
  onRowAction?: (variant: RowSheetVariant, row: TableRowData) => void;
  /** When true, the row shows a disclosure chevron that reveals a nested table. */
  expandable?: boolean;
  /** Visible viewport width, so the expanded detail fills the screen, not the
   *  table's wider scroll width. */
  detailWidth?: number;
}) {
  const [switchOn, setSwitchOn] = React.useState(row.switchOn);
  const [toggle, setToggle] = React.useState(row.toggle);
  const [expanded, setExpanded] = React.useState(false);

  // One renderer per column key — header and body share the same visible set,
  // so hiding a column (column-filters menu) drops both in lockstep.
  const cells: Record<ColumnKey, React.ReactNode> = {
    select: (
      <Checkbox
        checked={selected}
        onCheckedChange={onToggle}
        aria-label={`Select ${row.id}`}
      />
    ),
    status: <StatusChip tone={statusTone(row.status)}>{row.status}</StatusChip>,
    editable: (
      <CellEditable
        value={editableValue}
        onChange={onEditableChange}
        leading={editableIcons.leading}
        trailing={editableIcons.trailing}
      />
    ),
    dropdown: (
      <CellDropdown
        title={row.dropdown.title}
        description={row.dropdown.description}
      />
    ),
    descriptive: (
      <TwoLine
        title={row.descriptive.title}
        description={row.descriptive.description}
      />
    ),
    badge: <Badge variant={statusBadgeVariant(row.status)}>{row.status}</Badge>,
    statusBadge: (
      <span className="inline-flex items-center gap-2">
        <Avatar className="size-5">
          <AvatarFallback className="text-[10px]">U</AvatarFallback>
        </Avatar>
        <StatusChip tone={statusTone(row.statusBadge)}>{row.statusBadge}</StatusChip>
      </span>
    ),
    switch: (
      <Switch
        checked={switchOn}
        onCheckedChange={setSwitchOn}
        aria-label="Toggle row"
      />
    ),
    button: (
      <Button variant="outline" size="xs">
        Button
      </Button>
    ),
    iconDropdown: (
      <Button variant="outline" size="icon-sm" aria-label="Open">
        <CirclePlay />
      </Button>
    ),
    progress: <Progress value={row.progress} className="h-1.5 w-24" />,
    image: (
      <div className="size-8 rounded-md border border-border bg-foreground/90" />
    ),
    toggle: (
      <ToggleGroup
        type="single"
        variant="outline"
        size="sm"
        value={toggle}
        onValueChange={(v) => v && setToggle(v)}
      >
        <ToggleGroupItem value="bold" aria-label="Bold" className="px-2">
          <Bold className="size-4" />
        </ToggleGroupItem>
        <ToggleGroupItem value="italic" aria-label="Italic" className="px-2">
          <Italic className="size-4" />
        </ToggleGroupItem>
        <ToggleGroupItem value="underline" aria-label="Underline" className="px-2">
          <Underline className="size-4" />
        </ToggleGroupItem>
      </ToggleGroup>
    ),
    amount: (
      <HoverCard openDelay={120} closeDelay={80}>
        <HoverCardTrigger variant="link" className="ml-auto tabular-nums">
          {currency.format(row.amount)}
        </HoverCardTrigger>
        <HoverCardContent align="end" side="left" className="w-[380px]">
          <InvoiceCard />
        </HoverCardContent>
      </HoverCard>
    ),
    actions: (
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant="ghost" size="icon-sm" aria-label="Row actions">
            <MoreHorizontal />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          {onRowAction && (
            <>
              <DropdownMenuItem onSelect={() => onRowAction("narrow", row)}>
                <PanelRightOpen />
                View details
              </DropdownMenuItem>
              <DropdownMenuItem onSelect={() => onRowAction("wide", row)}>
                <Table2 />
                Tank list
              </DropdownMenuItem>
              <DropdownMenuItem onSelect={() => onRowAction("dense", row)}>
                <PackagePlus />
                Assign asset
              </DropdownMenuItem>
              <DropdownMenuSeparator />
            </>
          )}
          <DropdownMenuItem>
            <Pencil />
            Edit
          </DropdownMenuItem>
          <DropdownMenuItem>
            <Share2 />
            Share
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem variant="destructive">
            <Trash2 />
            Delete
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    ),
  };

  return (
    <>
      <TableRow
        data-state={selected ? "selected" : undefined}
        data-expanded={expanded ? "true" : undefined}
        // A subtle tint anchors the parent while its children are open, so the
        // parent row stays at least as prominent as the nested sub-table.
        // Drop the bottom divider when expanded so the green accent rail runs
        // seamlessly from this row into the nested block (no grey notch).
        className={cn(
          "h-14",
          expanded && "border-b-0 bg-fp-row-hover hover:bg-fp-row-hover"
        )}
      >
        {columns.map((col, ci) => (
          <TableCell
            key={col.key}
            className={cn(
              // Dropdown cells zero their padding so the trigger fills the whole
              // cell (full-cell hover, like the form table); others keep px-3.
              col.key === "dropdown" || col.key === "editable" ? "p-0" : "px-3",
              col.align === "right" && "text-right text-sm tabular-nums",
              // When expanded, carry the green accent up the parent row's left
              // edge so the line runs from the top of this row into the nested
              // detail below as one continuous rail.
              ci === 0 && expanded && "relative before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70"
            )}
          >
            {col.key === "status" && expandable ? (
              <div className="flex items-center gap-1.5">
                <button
                  type="button"
                  onClick={() => setExpanded((v) => !v)}
                  aria-expanded={expanded}
                  aria-label={expanded ? "Collapse row" : "Expand row"}
                  className="-ml-1 rounded p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                >
                  <ChevronRight
                    className={cn("size-4 transition-transform", expanded && "rotate-90")}
                  />
                </button>
                {cells[col.key]}
              </div>
            ) : (
              cells[col.key]
            )}
          </TableCell>
        ))}
      </TableRow>
      {expandable && expanded && (
        <TableRow className="hover:bg-transparent data-[state=selected]:bg-transparent">
          {/* Recessed surface spans the full row (end-to-end); the inner detail
              is pinned to the visible width so its columns stay comfortable. */}
          <TableCell colSpan={columns.length} className="bg-fp-surface-1b p-0">
            <NestedTable width={detailWidth} />
          </TableCell>
        </TableRow>
      )}
    </>
  );
}

import { ChevronDown, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { Checkbox } from "@/components/ui/checkbox";
import { TableCell, TableRow } from "@/components/ui/table";
import { formatMeasure } from "./grouping";

/*
  One group header row, shared by every table shell so grouping looks identical
  wherever it is turned on.

  It spans every column rather than sitting in one, because a group header is
  not a record — it belongs to the table, not to the columns. What it carries is
  fixed by the rule the engine encodes: label · count · the one summed measure
  for this list. A list picks that measure; nothing else on it adds up to
  something true.

  The depth-0 header sticks under the column header while its rows scroll, so
  you never lose track of which group you are reading. Nested headers do not
  stick: two stacked sticky bands eat the top of a short group.

  HEADERS INDENT, ROWS DO NOT. Indenting the rows too would push the checkbox
  column out from under its own header and break column alignment across groups
  — and column alignment is the thing a data grid is for. The header bands carry
  the nesting on their own.

  THE BAND FILL IS `--fp-lane`, MEASURED. The obvious pick, `--fp-surface-1a`,
  is #ffffff in light — identical to the table's own ground — so the band simply
  vanished there while looking correct in dark. `--muted` fails the same test the
  other way round (#1b2028 in dark, the content layer exactly). `--fp-lane` is
  #f4f5f8 / #2a2f37: distinct from the body in BOTH themes, and it already means
  "the band a group of rows lives in" in the DS's board view. `--fp-row-hover`
  would also have worked but is spoken for.
*/

export interface GroupHeaderRowProps {
  colSpan: number;
  depth: number;
  label: string;
  /** The dimension that produced the group — shown when nested, for context. */
  dimLabel: string;
  count: number;
  /** Summed measure, already totalled. Omit on a list with nothing to sum. */
  measure?: number;
  /** Unit for that measure, e.g. `gal`. Empty renders the bare number. */
  unit?: string;
  /** What one record is called here — "order", "asset", "account". */
  noun: string;
  collapsed: boolean;
  onToggle: () => void;
  /** Omitted on lists without row selection. */
  selection?: {
    state: boolean | "indeterminate";
    onChange: (checked: boolean) => void;
  };
}

/** 20px per level — enough to read as nesting, cheap enough to afford twice. */
const INDENT = 20;

export function GroupHeaderRow({
  colSpan,
  depth,
  label,
  dimLabel,
  count,
  measure,
  unit,
  noun,
  collapsed,
  onToggle,
  selection,
}: GroupHeaderRowProps) {
  return (
    <TableRow
      className={cn(
        "h-10 border-b border-fp-outline-1 hover:bg-transparent",
        // z-10 keeps it under the column header (z-20) and over the body rows.
        depth === 0 && "sticky top-10 z-10"
      )}
    >
      <TableCell colSpan={colSpan} className="bg-fp-lane p-0">
        {/* The header spans every column, so on a wide table it is far wider
            than the content layer on screen. Pinning the content block
            to the left edge of the horizontal scroll keeps the label, the count
            and the total on screen at any scroll position — right-aligning the
            total instead parked it off the right edge, visible only to someone
            who scrolled looking for it. */}
        <div
          className="sticky left-0 flex h-10 w-fit max-w-full items-center gap-2.5 pr-4"
          style={{ paddingLeft: 12 + depth * INDENT }}
        >
          {selection && (
            <Checkbox
              checked={selection.state}
              onCheckedChange={(c) => selection.onChange(c === true)}
              aria-label={`Select all ${count} ${noun}${count === 1 ? "" : "s"} in ${label}`}
            />
          )}
          <button
            type="button"
            onClick={onToggle}
            aria-expanded={!collapsed}
            className="flex min-w-0 items-center gap-2 rounded-sm text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            <span className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
              {collapsed ? (
                <ChevronRight className="size-4" />
              ) : (
                <ChevronDown className="size-4" />
              )}
            </span>
            {depth > 0 && (
              <span className="shrink-0 text-xs text-muted-foreground">
                {dimLabel}
              </span>
            )}
            <span className="truncate text-sm font-medium text-foreground">
              {label}
            </span>
            <span className="shrink-0 rounded-full bg-muted px-1.5 py-0.5 text-[11px] font-medium tabular-nums text-muted-foreground">
              {count}
            </span>
          </button>
          {/* Sits beside the count, not at the far right — see above. Absent
              entirely on a list with nothing to sum, rather than showing a
              zero that means "no measure" and reads as "none". */}
          {measure !== undefined && (
            <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
              {formatMeasure(measure, unit ?? "")}
            </span>
          )}
        </div>
      </TableCell>
    </TableRow>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import { TableHead } from "@/components/ui/table";
import { ColumnMoveGrip, ColumnResizeHandle } from "./ColumnHandles";
import type { UseTableColumnsResult } from "./useTableColumns";

/**
 * A table's column header. Render this instead of `<TableHead>` and the column
 * moves and resizes — there is nothing else to wire.
 *
 * WHAT IT CARRIES, so that no table has to remember it:
 *
 *  • the drag props that make the header the move target, and the keyboard
 *    ⌘/Ctrl + ← → that moves it without a pointer;
 *  • the drop indicator — the dragged header fades, the one it will land
 *    against draws a rule on the side it will land on;
 *  • `ColumnResizeHandle` on the right edge and `ColumnMoveGrip` at the label,
 *    both lit by this header's own hover and by nothing else;
 *  • `group/th`, `relative` and the focus ring the two of them depend on.
 *
 * A FIXED column gets none of it: the leading select box and the trailing
 * row-open cell are the frame a row is read inside rather than content, and the
 * trailing one is pinned to the right edge so it survives a sideways scroll.
 */
export function TableColumnHeader({
  cols,
  col,
  className,
  children,
  ...props
}: {
  /** The `useTableColumns` result. */
  cols: UseTableColumnsResult;
  col: { key: string; width: number };
} & React.ComponentProps<typeof TableHead>) {
  const fixed = cols.isFixed(col.key);
  const resize = cols.resizeProps(col);

  return (
    <TableHead
      {...cols.headerProps(col.key)}
      {...props}
      className={cn(
        "group/th relative",
        !fixed && "cursor-grab",
        // The column being dragged fades out of the way.
        "data-[dragging]:opacity-40",
        // The one it will land against draws a rule on the side it lands on.
        "before:pointer-events-none before:absolute before:inset-y-0 before:w-0.5 before:bg-transparent",
        "data-[drop=before]:before:left-0 data-[drop=before]:before:bg-ring",
        "data-[drop=after]:before:right-0 data-[drop=after]:before:bg-ring",
        "outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
        className
      )}
    >
      {/* The resize handle is FIRST so the move grip can be its peer and step
          aside once the pointer actually reaches the divider. */}
      {resize && <ColumnResizeHandle {...resize} />}
      {!fixed && <ColumnMoveGrip />}
      {children}
    </TableHead>
  );
}

import type { StatusTone } from "@/components/ui/status-chip";
import type {
  ColumnDef,
  ColumnKey,
  RowStatus,
  SortState,
  TableRow,
} from "./types";
import type { GroupDim } from "./grouping";

/*
  Column order + widths taken verbatim from the Figma column frames:
  select=40, status(Static)=145.9, dropdown=172, descriptive=145.9, badge=85,
  statusBadge=145.9, switch..amount=145.9 each, actions=44.
  `sortable` flags reflect the ↕ glyphs read from the screenshot (ASSUMPTION —
  the exact set is a component variant prop not exposed by the Figma metadata).
*/
export const COLUMNS: ColumnDef[] = [
  { key: "select", label: "", width: 40 },
  { key: "status", label: "Static", width: 145.9, sortable: true },
  { key: "editable", label: "Editable", width: 175, sortable: true },
  { key: "dropdown", label: "Dropdown", width: 172 },
  { key: "descriptive", label: "Descriptive Text", width: 145.9 },
  { key: "badge", label: "Badge", width: 85 },
  { key: "statusBadge", label: "Badge", width: 145.9 },
  { key: "switch", label: "Switch", width: 145.9, sortable: true },
  { key: "button", label: "Button", width: 145.9 },
  { key: "iconDropdown", label: "Dropdown", width: 145.9 },
  { key: "progress", label: "Progress", width: 145.9, sortable: true },
  { key: "image", label: "Image", width: 145.9 },
  { key: "toggle", label: "Toggle Group", width: 145.9 },
  { key: "amount", label: "Amount", width: 145.9, sortable: true, align: "right" },
  { key: "actions", label: "", width: 44 },
];

const STATUS_CYCLE: RowStatus[] = [
  "Success",
  "Success",
  "Processing",
  "Success",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
];

const AMOUNTS = [630.44, 812.1, 199.99, 475.22, 275.43, 1040.0, 56.75, 920.18];

/** 1,000 sample rows so pagination is exercised against a realistic dataset. */
export const SAMPLE_ROWS: TableRow[] = Array.from({ length: 1000 }, (_, i) => {
  const status = STATUS_CYCLE[i % STATUS_CYCLE.length];
  return {
    id: `row-${i + 1}`,
    status,
    editable: "Editable Text",
    dropdown: { title: "Table Cell Text", description: "Description Text" },
    descriptive: { title: "Table Cell Text", description: "Description Text" },
    badge: "Badge",
    statusBadge: status,
    switchOn: i % 3 === 0,
    progress: 5 + ((i * 7) % 95),
    toggle: "bold",
    amount: AMOUNTS[i % AMOUNTS.length] + (i % 13),
  };
});

/**
 * THE status mapping for this dataset. Per the DS's colour governance a status
 * carries no colour until a usage rule binds it — the DS ships `StatusTone`
 * channels, and this application-side function is that binding. Everything
 * else that needs a status colour derives from here, so there is one
 * vocabulary rather than two.
 */
export function statusTone(status: RowStatus): StatusTone {
  switch (status) {
    case "Success":
      return "success";
    case "Processing":
      return "processing";
    case "Failed":
      return "failed";
  }
}

/**
 * Badge variant for a row status, DERIVED from `statusTone` so the filled-badge
 * treatment cannot drift from the chip treatment.
 * DS gap: the badge palette has no green "success" variant, so success maps to
 * `verified`; processing → neutral `secondary`; failed → `destructive`.
 */
export function statusBadgeVariant(
  status: RowStatus
): "verified" | "secondary" | "destructive" {
  switch (statusTone(status)) {
    case "success":
      return "verified";
    case "processing":
      return "secondary";
    default:
      return "destructive";
  }
}

/** Value a column sorts on. Columns without per-row data sort as a no-op. */
function sortValue(row: TableRow, key: ColumnKey): string | number {
  switch (key) {
    case "status":
      return row.status;
    case "switch":
      return row.switchOn ? 1 : 0;
    case "progress":
      return row.progress;
    case "amount":
      return row.amount;
    default:
      return 0;
  }
}

/** Pure sort — returns a new array; `null` leaves the order untouched. */
export function sortRows(rows: TableRow[], sort: SortState | null): TableRow[] {
  if (!sort) return rows;
  const factor = sort.dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const av = sortValue(a, sort.key);
    const bv = sortValue(b, sort.key);
    if (av < bv) return -1 * factor;
    if (av > bv) return 1 * factor;
    return 0;
  });
}

/**
 * Page-number windowing — Figma "FP Pagination" rules (27631:11152):
 * anchor first + last, show `siblings` either side of the current page, and
 * collapse the gaps into "ellipsis". Fixed slot count keeps the bar from
 * reflowing as you navigate.
 */
export function paginationRange(
  current: number,
  total: number,
  siblings = 1
): (number | "ellipsis")[] {
  const range = (start: number, end: number) =>
    Array.from({ length: end - start + 1 }, (_, i) => start + i);

  // first + last + current + 2 siblings + 2 ellipsis slots
  const totalSlots = siblings * 2 + 5;
  if (totalSlots >= total) return range(1, total);

  const left = Math.max(current - siblings, 1);
  const right = Math.min(current + siblings, total);
  const showLeftDots = left > 2;
  const showRightDots = right < total - 1;
  const edgeCount = 3 + 2 * siblings;

  if (!showLeftDots && showRightDots) {
    return [...range(1, edgeCount), "ellipsis", total];
  }
  if (showLeftDots && !showRightDots) {
    return [1, "ellipsis", ...range(total - edgeCount + 1, total)];
  }
  return [1, "ellipsis", ...range(left, right), "ellipsis", total];
}

/*
  What the sample list can be grouped BY.

  A property of the DATA, not of the Group By control — which is why the menu
  and the engine both take these as a prop. Three dimensions, not thirteen: on
  this dataset `badge`, `toggle`, `dropdown`, `descriptive` and `editable` are
  the same string on all 1,000 rows, so offering them would hand you a control
  that produces one group containing everything. A dimension with no VARIANCE
  organises exactly as little as one with no backing field.

  PROGRESS SHOWS THE OTHER SHAPE: `valuesOf` returns a DERIVED label, not a
  stored one. Grouping by a raw 0–100 number would make a thousand groups of
  one; the bands are what anyone actually wants to ask about, and `order` keeps
  them in numeric sequence rather than alphabetical.

  MEASURE: Amount. It is the one column on this list that sums to something
  true, so it is what every group header totals.
*/
export const SAMPLE_GROUP_DIMS: GroupDim<TableRow>[] = [
  {
    key: "status",
    label: "Static",
    hides: "status",
    // A real lifecycle, so the groups follow it rather than the alphabet.
    order: ["Processing", "Success", "Failed"],
    valuesOf: (r) => [r.status],
  },
  {
    key: "switch",
    label: "Switch",
    hides: "switch",
    // Two groups answering "what is off", which is the question worth asking.
    order: ["Off", "On"],
    valuesOf: (r) => [r.switchOn ? "On" : "Off"],
  },
  {
    key: "progress",
    label: "Progress",
    hides: "progress",
    order: ["0–24%", "25–49%", "50–74%", "75–100%"],
    valuesOf: (r) => [
      r.progress < 25
        ? "0–24%"
        : r.progress < 50
          ? "25–49%"
          : r.progress < 75
            ? "50–74%"
            : "75–100%",
    ],
  },
];

/*
  Grouping engine — screen-agnostic, and the single source of grouping
  behaviour for every list that offers it.

  It produces DATA, not markup: `groupRows` returns a flat render list of
  group-header and row nodes with a depth on each, so any table shell can render
  grouping without owning the logic. Two shells that each implemented this would
  drift within a release, and the drift would be in the totals.

  Three rules are enforced here rather than left to each screen:

  1. GROUP BY WHAT YOU WANT TOTALS FOR. Every group header carries a count and
     one summed measure — the only column on each list that adds up to something
     true (gallons, units, ship-tos, capacity). `measureOf` supplies it.

  2. DEGENERATE LEVELS ARE SKIPPED. A second dimension that yields exactly one
     child covering its whole parent tells the reader nothing and costs a row
     plus an indent — Customer › Ship To, wherever an account happens to have a
     single site. The header is dropped and the rows rise to the parent.

  3. MULTI-VALUE DIMENSIONS DUPLICATE. A record with three products belongs to
     three product groups. `multi` marks those dimensions so the menu can flag
     them and the footer can say the counts deliberately over-sum.

  Two levels is the cap. It is enforced by the menu, not here.
*/

/** The label a row gets when it has no value for the dimension. Sorts last. */
export const NO_VALUE = "—";

export interface GroupDim<Row> {
  key: string;
  label: string;
  /**
   * A row can land in several groups, so group counts sum past the list total.
   * Marked in the menu and stated in the footer.
   */
  multi?: boolean;
  /** Every group this row belongs to. Empty ⇒ the `NO_VALUE` group. */
  valuesOf: (row: Row) => string[];
  /**
   * The column this dimension is rendered in. While grouped by it, that column
   * repeats its own header on every row, so the table hides it and gives the
   * width back.
   */
  hides?: string;
  /**
   * Group order, for dimensions with a meaningful sequence (a status
   * lifecycle). Anything not listed falls after, alphabetically.
   */
  order?: string[];
}

export type GroupNode<Row> =
  | {
      kind: "group";
      /** Path-unique — `status:Assigned/customer:Morris Group`. */
      id: string;
      depth: number;
      label: string;
      /** The dimension that produced it, for the header's eyebrow. */
      dimLabel: string;
      /** Rows beneath, including those inside a collapsed child. */
      count: number;
      /** Summed measure, or `undefined` on a list with nothing to sum. */
      measure?: number;
      /**
       * The rows this header owns, collapsed or not — so the header checkbox
       * selects the whole group rather than the part that happens to be drawn.
       */
      rowIds: string[];
    }
  | { kind: "row"; id: string; depth: number; row: Row };

interface Bucket<Row> {
  id: string;
  label: string;
  dimLabel: string;
  rows: Row[];
  children: Bucket<Row>[] | null;
}

function compareLabels(a: string, b: string, order?: string[]): number {
  // The empty group is always last: it is the exception, not the first case.
  if (a === NO_VALUE) return b === NO_VALUE ? 0 : 1;
  if (b === NO_VALUE) return -1;
  if (order) {
    const ia = order.indexOf(a);
    const ib = order.indexOf(b);
    if (ia !== -1 || ib !== -1) {
      if (ia === -1) return 1;
      if (ib === -1) return -1;
      return ia - ib;
    }
  }
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" });
}

function bucketize<Row>(
  rows: Row[],
  dim: GroupDim<Row>,
  parentId: string
): Bucket<Row>[] {
  const byLabel = new Map<string, Row[]>();
  for (const row of rows) {
    const values = dim.valuesOf(row);
    const labels = values.length > 0 ? values : [NO_VALUE];
    for (const label of labels) {
      const bucket = byLabel.get(label);
      if (bucket) bucket.push(row);
      else byLabel.set(label, [row]);
    }
  }
  return [...byLabel.entries()]
    .sort((a, b) => compareLabels(a[0], b[0], dim.order))
    .map(([label, bucketRows]) => ({
      id: `${parentId}${parentId ? "/" : ""}${dim.key}:${label}`,
      label,
      dimLabel: dim.label,
      rows: bucketRows,
      children: null,
    }));
}

export interface GroupResult<Row> {
  nodes: GroupNode<Row>[];
  /** Every group id in the tree, so "collapse all" needs no second walk. */
  groupIds: string[];
  /** Headers actually rendered — the footer's "N groups". */
  groupCount: number;
  /** Distinct rows, which is NOT the sum of group counts on a multi dimension. */
  rowCount: number;
  /** True when any active dimension duplicates rows across groups. */
  overCounts: boolean;
}

/**
 * Build the render list.
 *
 * `collapsed` holds the ids of collapsed groups; their descendants are omitted
 * from `nodes` but still counted in every ancestor header, which is the whole
 * point of collapsing — the totals stay true while the rows go away.
 */
export function groupRows<Row>(
  rows: Row[],
  dims: GroupDim<Row>[],
  options: {
    rowId: (row: Row) => string;
    /** The one column that sums to something true. Defaults to a plain count. */
    measureOf?: (row: Row) => number;
    collapsed?: ReadonlySet<string>;
  }
): GroupResult<Row> {
  const { rowId, measureOf, collapsed } = options;
  /* NOT EVERY LIST HAS A MEASURE. Vendors, products, users — nothing on the row
     sums to something true, and a header reading "0" next to a real count is
     worse than a header that simply does not claim one. `undefined` is the
     honest answer, and the header and footer both omit it. */
  const measure = (bucketRows: Row[]) =>
    measureOf ? bucketRows.reduce((n, r) => n + measureOf(r), 0) : undefined;

  if (dims.length === 0) {
    return {
      nodes: rows.map((row) => ({
        kind: "row" as const,
        id: rowId(row),
        depth: 0,
        row,
      })),
      groupIds: [],
      groupCount: 0,
      rowCount: rows.length,
      overCounts: false,
    };
  }

  const nodes: GroupNode<Row>[] = [];
  const groupIds: string[] = [];
  let groupCount = 0;

  const walk = (bucketRows: Row[], depth: number, parentId: string) => {
    const dim = dims[depth];
    if (!dim) {
      for (const row of bucketRows) {
        nodes.push({
          kind: "row",
          // Path-scoped: on a multi dimension the same row appears under
          // several groups, and a bare row id would collide as a React key.
          id: `${parentId}#${rowId(row)}`,
          depth,
          row,
        });
      }
      return;
    }

    const buckets = bucketize(bucketRows, dim, parentId);

    // Rule 2 — a level with one child covering the whole parent adds an indent
    // and no information. Drop the header, keep descending.
    if (depth > 0 && buckets.length === 1 && buckets[0].rows.length === bucketRows.length) {
      walk(bucketRows, depth + 1, parentId);
      return;
    }

    for (const bucket of buckets) {
      groupIds.push(bucket.id);
      groupCount += 1;
      nodes.push({
        kind: "group",
        id: bucket.id,
        depth,
        label: bucket.label,
        dimLabel: bucket.dimLabel,
        count: bucket.rows.length,
        measure: measure(bucket.rows),
        rowIds: bucket.rows.map(rowId),
      });
      if (!collapsed?.has(bucket.id)) {
        walk(bucket.rows, depth + 1, bucket.id);
      }
    }
  };

  walk(rows, 0, "");

  return {
    nodes,
    groupIds,
    groupCount,
    rowCount: rows.length,
    overCounts: dims.some((d) => d.multi),
  };
}

/** The columns to hide while these dimensions are active (rule: no column repeats its own group header). */
export function columnsHiddenByGrouping<Row>(dims: GroupDim<Row>[]): string[] {
  return dims.map((d) => d.hides).filter((k): k is string => Boolean(k));
}

/** `24,132 gal` — group headers, and the footer, read the same formatting. */
export function formatMeasure(value: number, unit: string): string {
  return `${value.toLocaleString("en-US")}${unit ? ` ${unit}` : ""}`;
}

/**
 * Tri-state for a group's header checkbox. Reads the group's WHOLE membership,
 * so a collapsed group still reports honestly instead of describing the rows
 * that happen to be drawn.
 */
export function groupSelectionState(
  rowIds: string[],
  selected: ReadonlySet<string>
): boolean | "indeterminate" {
  if (rowIds.length === 0) return false;
  let hit = 0;
  for (const id of rowIds) if (selected.has(id)) hit += 1;
  if (hit === 0) return false;
  return hit === rowIds.length ? true : "indeterminate";
}

export type RowStatus = "Success" | "Processing" | "Failed";

export interface TwoLineText {
  title: string;
  description: string;
}

/** One row of the data table. Each field maps to a Figma column. */
export interface TableRow {
  id: string;
  /** col "Static" — plain status label */
  status: RowStatus;
  /** col "Editable" — inline-editable text, same treatment as a Static cell */
  editable: string;
  /** col "Dropdown" — two-line text with a trailing chevron */
  dropdown: TwoLineText;
  /** col "Descriptive Text" — two-line text */
  descriptive: TwoLineText;
  /** col "Badge" — short badge label */
  badge: string;
  /** col "Badge" (avatar + status) */
  statusBadge: RowStatus;
  /** col "Switch" */
  switchOn: boolean;
  /** col "Progress" 0–100 */
  progress: number;
  /** col "Toggle Group" — selected toggle value */
  toggle: string;
  /** col "Amount" — currency value */
  amount: number;
}

export type ColumnKey =
  | "select"
  | "status"
  | "editable"
  | "dropdown"
  | "descriptive"
  | "badge"
  | "statusBadge"
  | "switch"
  | "button"
  | "iconDropdown"
  | "progress"
  | "image"
  | "toggle"
  | "amount"
  | "actions";

export interface ColumnDef {
  key: ColumnKey;
  label: string;
  /** px width, taken from Figma column frame widths */
  width: number;
  sortable?: boolean;
  align?: "left" | "right" | "center";
}

export type SortDir = "asc" | "desc";

export interface SortState {
  key: ColumnKey;
  dir: SortDir;
}

import * as React from "react";

/*
  COLUMN ORDER, AS A REORDERABLE THING.

  A table's column order is the reader's, not the schema's. Which two columns
  sit side by side is what makes a comparison possible at a glance, and the
  right pair differs by who is looking — dispatch wants Driver next to Planned
  Date, accounting wants Qty next to Status. Hiding the columns in between is
  the workaround people reach for when they cannot move them, and it costs them
  the columns.

  WHAT STAYS PUT. Some columns are structure rather than content: the leading
  select box and the trailing row-open control are the frame the row is read
  inside, and the trailing one is pinned to the right edge so it survives a
  sideways scroll. Those are `fixed` — not draggable, and not droppable either,
  so a column cannot be dropped outside the frame.

  DUAL MODE, like the rest of this folder: pass `value` + `onChange` to keep the
  order in a saved view; leave them off and the hook owns it.
*/

export interface UseColumnOrderOptions {
  /** Every column key, in the order the table declares them. */
  keys: string[];
  /** Keys that cannot move and cannot be moved past — e.g. select, actions. */
  fixed?: string[];
  /** Supply with `onChange` to control the order from outside. */
  value?: string[];
  onChange?: (next: string[]) => void;
  /**
   * Asked at the moment a drag would start. Return false to refuse it — the
   * table uses this to stand down while a pointer is resizing a divider, since
   * both gestures begin on a header and only one of them can be meant.
   */
  canDrag?: () => boolean;
}

export interface ColumnHeaderDragProps {
  draggable: boolean;
  onDragStart?: (e: React.DragEvent) => void;
  onDragOver?: (e: React.DragEvent) => void;
  onDragLeave?: () => void;
  onDrop?: (e: React.DragEvent) => void;
  onDragEnd?: () => void;
  onKeyDown?: (e: React.KeyboardEvent) => void;
  tabIndex?: number;
  title?: string;
  /** Set while this header is the one being dragged. */
  "data-dragging"?: "" | undefined;
  /** "before" | "after" — which edge the drop indicator sits on. */
  "data-drop"?: "before" | "after" | undefined;
}

export interface UseColumnOrderResult {
  order: string[];
  /** Sorts a column list into the current order. Unknown keys keep their place. */
  arrange: <T extends { key: string }>(cols: T[]) => T[];
  /** Everything a `<th>` needs. Spread it. */
  headerProps: (key: string) => ColumnHeaderDragProps;
  /** The key currently being dragged, or null. */
  dragging: string | null;
}

export function useColumnOrder({
  keys,
  fixed = [],
  value,
  onChange,
  canDrag,
}: UseColumnOrderOptions): UseColumnOrderResult {
  const [own, setOwn] = React.useState<string[]>(keys);
  const controlled = value !== undefined;
  const order = controlled ? value : own;

  /* NEW COLUMNS ARE NOT LOST. A saved order predates any column added since,
     so anything the order does not mention is appended in its declared
     position rather than dropped — a stale view should cost you the ordering,
     never the column. */
  const effective = React.useMemo(() => {
    const known = order.filter((k) => keys.includes(k));
    const missing = keys.filter((k) => !known.includes(k));
    if (missing.length === 0) return known;
    const out = [...known];
    for (const k of missing) {
      const at = keys.indexOf(k);
      const before = keys.slice(0, at).reverse().find((p) => out.includes(p));
      out.splice(before ? out.indexOf(before) + 1 : 0, 0, k);
    }
    return out;
  }, [order, keys]);

  const commit = (next: string[]) => {
    if (!controlled) setOwn(next);
    onChange?.(next);
  };

  /* THE KEY LIVES IN A REF AS WELL AS IN STATE. `dragover` can arrive in the
     same tick as `dragstart` — a synthetic drag, or a fast pointer — and a
     handler closed over state that has not re-rendered yet would read null and
     ignore the whole drag. State drives the styling; the ref answers the
     handlers. */
  type Over = { key: string; side: "before" | "after" } | null;
  const dragRef = React.useRef<string | null>(null);
  const overRef = React.useRef<Over>(null);
  const [dragging, setDragging] = React.useState<string | null>(null);
  const [over, setOverState] = React.useState<Over>(null);
  const setOver = (next: Over) => {
    overRef.current = next;
    setOverState(next);
  };

  const isFixed = (k: string) => fixed.includes(k);

  /** Puts `key` where `target` is, on the given side. */
  const move = (key: string, target: string, side: "before" | "after") => {
    if (key === target || isFixed(key) || isFixed(target)) return;
    const next = effective.filter((k) => k !== key);
    const at = next.indexOf(target);
    if (at === -1) return;
    next.splice(side === "before" ? at : at + 1, 0, key);
    commit(next);
  };

  /** One step left or right, skipping nothing — the keyboard equivalent. */
  const nudge = (key: string, delta: -1 | 1) => {
    const movable = effective.filter((k) => !isFixed(k));
    const at = movable.indexOf(key);
    const to = at + delta;
    if (at === -1 || to < 0 || to >= movable.length) return;
    const next = effective.filter((k) => k !== key);
    next.splice(next.indexOf(movable[to]) + (delta === 1 ? 1 : 0), 0, key);
    commit(next);
  };

  const headerProps = (key: string): ColumnHeaderDragProps => {
    if (isFixed(key)) return { draggable: false };
    return {
      draggable: true,
      tabIndex: 0,
      /* The only discoverable place to say so — a header that can be dragged
         looks exactly like one that cannot. */
      title: "Drag to reorder. ⌘/Ctrl + ← → moves it one column.",
      onDragStart: (e) => {
        if (canDrag && !canDrag()) {
          e.preventDefault();
          return;
        }
        dragRef.current = key;
        setDragging(key);
        e.dataTransfer.effectAllowed = "move";
        // Firefox refuses to start a drag without payload.
        e.dataTransfer.setData("text/plain", key);
      },
      onDragOver: (e) => {
        const from = dragRef.current;
        if (!from || from === key) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
        /* WHICH SIDE depends on where in the header the pointer is, so the
           column lands where the indicator says it will rather than always
           on one side of the target. */
        const r = e.currentTarget.getBoundingClientRect();
        setOver({ key, side: e.clientX < r.left + r.width / 2 ? "before" : "after" });
      },
      onDragLeave: () => {
        if (overRef.current?.key === key) setOver(null);
      },
      onDrop: (e) => {
        e.preventDefault();
        const from = dragRef.current;
        const to = overRef.current;
        if (from && to?.key === key) move(from, key, to.side);
        dragRef.current = null;
        setDragging(null);
        setOver(null);
      },
      onDragEnd: () => {
        dragRef.current = null;
        setDragging(null);
        setOver(null);
      },
      onKeyDown: (e) => {
        /* WITH A MODIFIER, because a bare arrow on a focused header is how you
           get to the next one. */
        if (!e.metaKey && !e.ctrlKey) return;
        if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
        e.preventDefault();
        nudge(key, e.key === "ArrowLeft" ? -1 : 1);
      },
      "data-dragging": dragging === key ? "" : undefined,
      "data-drop": over?.key === key ? over.side : undefined,
    };
  };

  return {
    order: effective,
    arrange: <T extends { key: string }>(cols: T[]) =>
      [...cols].sort((a, b) => effective.indexOf(a.key) - effective.indexOf(b.key)),
    headerProps,
    dragging,
  };
}

import * as React from "react";

/*
  COLUMN WIDTH, AS A DRAGGABLE THING.

  Widths ship as a guess about content nobody has seen. A customer list where
  every name is thirty characters and a list where every name is eight want
  different columns, and the reader is the only one who knows which they have.
  Truncation is not a fit — it is the table telling you the value is there and
  you may not read it.

  THE DIVIDER RESIZES; THE HEADER MOVES. Both gestures start on a header and
  they must not compete, so they are given different targets and different
  cursors: the boundary between two columns is where every spreadsheet puts
  resize, so that is what it does here, and the header's body is what drags the
  column somewhere else. `canDrag` exists so the reorder hook can be told to
  stand down while a resize is in flight — a pointer held on the divider must
  not also start a column drag.

  DUAL MODE, like the rest of this folder: pass `value` + `onChange` to keep the
  widths in a saved view; leave them off and the hook owns them.
*/

export interface UseColumnWidthsOptions {
  /** Keys that cannot be resized — the select box and the pinned row-open cell. */
  fixed?: string[];
  /** Floor, in px. A column narrower than this holds nothing. Default 64. */
  min?: number;
  /** Supply with `onChange` to control the widths from outside. */
  value?: Record<string, number>;
  onChange?: (next: Record<string, number>) => void;
}

export interface ColumnResizeProps {
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  onLostPointerCapture: () => void;
  onDoubleClick: () => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  tabIndex: number;
  role: "separator";
  "aria-orientation": "vertical";
  "aria-label": string;
  draggable: false;
  "data-resizing"?: "" | undefined;
}

export interface UseColumnWidthsResult {
  /** The width to render — the reader's if they set one, else the declared one. */
  widthOf: (col: { key: string; width: number }) => number;
  /** Everything the divider handle needs. Spread it. Null for a fixed column. */
  resizeProps: (col: { key: string; width: number }) => ColumnResizeProps | null;
  /** True while a pointer is dragging a divider — read it, do not render on it. */
  isResizing: () => boolean;
  /** The key being resized, for styling. */
  resizing: string | null;
}

export function useColumnWidths({
  fixed = [],
  min = 64,
  value,
  onChange,
}: UseColumnWidthsOptions = {}): UseColumnWidthsResult {
  const [own, setOwn] = React.useState<Record<string, number>>({});
  const controlled = value !== undefined;
  const widths = controlled ? value : own;

  const commit = (next: Record<string, number>) => {
    if (!controlled) setOwn(next);
    onChange?.(next);
  };

  /* A REF, NOT STATE, for the live drag: `pointermove` fires far faster than
     React re-renders, and a handler reading a stale start point would make the
     column jump back and forth as the two disagreed. */
  const drag = React.useRef<{ key: string; x: number; from: number } | null>(null);
  const [resizing, setResizing] = React.useState<string | null>(null);

  /* A MISSED POINTERUP MUST NOT STRAND THE FLAG. The pointer can be released
     outside the window, or the handle can unmount under it, and either way the
     element's own handler never runs — leaving `drag.current` set, which tells
     the reorder hook to refuse every column drag from then on. One control
     quietly disabling another until reload is the worst kind of bug to find, so
     the release is watched on the window too, for as long as a resize is live. */
  React.useEffect(() => {
    if (!resizing) return;
    const end = () => {
      drag.current = null;
      setResizing(null);
    };
    window.addEventListener("pointerup", end);
    window.addEventListener("pointercancel", end);
    return () => {
      window.removeEventListener("pointerup", end);
      window.removeEventListener("pointercancel", end);
    };
  }, [resizing]);

  const setWidth = (key: string, px: number) =>
    commit({ ...widths, [key]: Math.max(min, Math.round(px)) });

  const resizeProps = (col: { key: string; width: number }) => {
    if (fixed.includes(col.key)) return null;
    const current = widths[col.key] ?? col.width;
    return {
      role: "separator" as const,
      "aria-orientation": "vertical" as const,
      "aria-label": "Resize column",
      tabIndex: 0,
      /* The handle sits inside a draggable `<th>`; without this the browser
         starts a column drag the moment the pointer moves. */
      draggable: false as const,
      onPointerDown: (e: React.PointerEvent) => {
        e.preventDefault();
        e.stopPropagation();
        (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
        drag.current = { key: col.key, x: e.clientX, from: current };
        setResizing(col.key);
      },
      onPointerMove: (e: React.PointerEvent) => {
        const d = drag.current;
        if (!d || d.key !== col.key) return;
        setWidth(col.key, d.from + (e.clientX - d.x));
      },
      onPointerUp: (e: React.PointerEvent) => {
        (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
        drag.current = null;
        setResizing(null);
      },
      onLostPointerCapture: () => {
        drag.current = null;
        setResizing(null);
      },
      /* BACK TO THE DECLARED WIDTH — the same double-click a spreadsheet gives
         you, and the only way back once a column has been dragged to nothing. */
      onDoubleClick: () => {
        const next = { ...widths };
        delete next[col.key];
        commit(next);
      },
      onKeyDown: (e: React.KeyboardEvent) => {
        if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
        e.preventDefault();
        setWidth(col.key, current + (e.key === "ArrowLeft" ? -16 : 16));
      },
      "data-resizing": resizing === col.key ? ("" as const) : undefined,
    };
  };

  return {
    widthOf: (col) => widths[col.key] ?? col.width,
    resizeProps,
    isResizing: () => drag.current !== null,
    resizing,
  };
}

import * as React from "react";
import { useColumnOrder, type ColumnHeaderDragProps } from "./useColumnOrder";
import { useColumnWidths, type ColumnResizeProps } from "./useColumnWidths";

/*
  THE TABLE'S COLUMN BEHAVIOUR, IN ONE CALL.

  Reordering and resizing are not features a table opts into — they are what a
  column IS for anyone reading one. Split across two hooks and five header
  classes they were something each table had to remember to wire, and the one
  that forgot looked identical to the one that could not. This composes them,
  wires the guard between them, and hands the result to `TableColumnHeader`,
  which is the only thing a table has to render.

  A new table gets both by using that header. There is no "enable" flag, because
  a table that does not want them is a table whose columns the reader may not
  arrange, and that is not a default anyone should be able to reach for by
  omission.
*/

export interface UseTableColumnsOptions {
  /** Every column key, in the order the table declares them. */
  keys: string[];
  /**
   * Structure, not content — the leading select box and the trailing row-open
   * cell. These neither move nor resize, and nothing can be dropped past them.
   */
  fixed?: string[];
  /** Supply with `onOrderChange` to keep the order in a saved view. */
  order?: string[];
  onOrderChange?: (next: string[]) => void;
  /** Supply with `onWidthsChange` to keep the widths in a saved view. */
  widths?: Record<string, number>;
  onWidthsChange?: (next: Record<string, number>) => void;
}

export interface UseTableColumnsResult {
  /** Sorts a column list into the reader's order. */
  arrange: <T extends { key: string }>(cols: T[]) => T[];
  /** The width to render — the reader's if they set one, else the declared one. */
  widthOf: (col: { key: string; width: number }) => number;
  /** True for a column that is structure rather than content. */
  isFixed: (key: string) => boolean;
  /** Internals `TableColumnHeader` spreads. Callers should not need these. */
  headerProps: (key: string) => ColumnHeaderDragProps;
  resizeProps: (col: { key: string; width: number }) => ColumnResizeProps | null;
}

export function useTableColumns({
  keys,
  fixed = [],
  order,
  onOrderChange,
  widths,
  onWidthsChange,
}: UseTableColumnsOptions): UseTableColumnsResult {
  const width = useColumnWidths({
    fixed,
    value: widths,
    onChange: onWidthsChange,
  });
  /* THE GUARD LIVES HERE so no table can forget it: both gestures start on a
     header, and without this the browser starts a column drag out of a resize
     press. */
  const orderState = useColumnOrder({
    keys,
    fixed,
    value: order,
    onChange: onOrderChange,
    canDrag: () => !width.isResizing(),
  });

  const fixedSet = React.useMemo(() => new Set(fixed), [fixed]);

  return {
    arrange: orderState.arrange,
    widthOf: width.widthOf,
    isFixed: (key) => fixedSet.has(key),
    headerProps: orderState.headerProps,
    resizeProps: width.resizeProps,
  };
}

